// --- Types ---

interface ApiCallEntry {
  timestamp: string;
  method: string;
  url: string;
  status: number;
  duration_ms: number;
  request_headers: Record<string, string>;
  request_size_bytes: number;
  response_size_bytes: number;
  type: string;
  error_code?: string;
  error_body?: string;
  trace_id?: string;
  tempo_trace_id?: string;
  support_trace_id?: string;
  search_trace_id?: string;
  transport?: 'rest' | 'websocket';
  query_meta?: {
    raw_query?: string;
    is_fulltext?: boolean | string;
    search_trace_id?: string;
  };
  client_timing?: Record<string, unknown>;
}

interface ConsoleEntry {
  timestamp: string;
  level: string;
  message: string;
  args: unknown[];
}

interface ErrorEntry {
  timestamp: string;
  type: string;
  message: string;
  stack: string;
  source: string;
  breadcrumbs: unknown[];
}

export interface DebugSnapshot {
  version: '1.0';
  generated_at: string;
  trace_summary: {
    primary_trace_id?: string;
    latest_support_trace_id?: string;
    latest_search_trace_id?: string;
    latest_tempo_trace_id?: string;
    source?: string;
  };
  environment: Record<string, unknown>;
  user_context: Record<string, unknown>;
  api_calls: ApiCallEntry[];
  websocket: Record<string, unknown>;
  errors: ErrorEntry[];
  console_log: ConsoleEntry[];
  performance: Record<string, unknown>;
  network: Record<string, unknown>;
  storage: Record<string, unknown>;
  feature_flags: Record<string, unknown>;
  service_versions: Array<{
    app: string;
    version: string;
    status: string;
    deployment_date: string;
  }>;
}

// --- Ring Buffers (60 items each) ---

const BUFFER_SIZE = 60;
const apiCallBuffer = new RingBuffer<ApiCallEntry>(BUFFER_SIZE);
const consoleBuffer = new RingBuffer<ConsoleEntry>(BUFFER_SIZE);
const errorBuffer = new RingBuffer<ErrorEntry>(BUFFER_SIZE);

export function getApiCallBuffer() {
  return apiCallBuffer;
}
export function getConsoleBuffer() {
  return consoleBuffer;
}
export function getErrorBuffer() {
  return errorBuffer;
}

/**
 * Push a WebSocket-delivered call into the same buffer the axios
 * interceptor uses. Lets the perf report show WS dashboard timings
 * alongside REST timings, with a `transport: "websocket"` marker so
 * you can tell which path actually carried the request.
 *
 * Called from `websocket.store.ts:sendMessageByType` — kept as a
 * separate export so the store doesn't depend on the snapshot shape.
 */
export function recordWsCall(entry: {
  type: string;
  request_id?: string;
  support_trace_id?: string;
  search_trace_id?: string;
  duration_ms: number;
  status: 'ok' | 'error' | 'timeout';
  payload?: Record<string, unknown>;
  response_size_bytes?: number;
  request_size_bytes?: number;
  client_timing?: Record<string, unknown>;
}): void {
  // Keep slow-call store in sync with the REST path so the
  // PerformanceAnalysisDialog "Slow API Calls" section surfaces WS
  // delays the same way it surfaces REST delays.
  const url =
    `ws://${entry.type}` +
    (entry.request_id ? `?request_id=${entry.request_id}` : '');

  // messageType → report "type" classifier. Dashboard channels land under
  // the same "dashboard.documents" key as REST so the Slow Queries by Type
  // breakdown doesn't split them.
  const type =
    entry.type === 'dashboard' || entry.type === 'dashboard_update'
      ? 'dashboard.documents'
      : `ws.${entry.type.toLowerCase()}`;

  if (entry.duration_ms >= SLOW_CALL_THRESHOLD_MS) {
    recordSlowCall({
      url,
      method: 'WS',
      duration: entry.duration_ms,
      status: entry.status === 'ok' ? 200 : 0,
      type,
      timestamp: new Date().toISOString(),
      supportTraceId: entry.support_trace_id || entry.search_trace_id,
      searchTraceId: entry.search_trace_id,
    });
  }

  // Surface the raw_query / is_fulltext fields if this was a dashboard
  // request, so the snapshot shows the actual filter inline instead of
  // forcing the reader to URL-decode the URL.
  let queryMeta: ApiCallEntry['query_meta'];
  if (
    entry.payload &&
    (entry.payload.raw_query || entry.payload.is_fulltext !== undefined)
  ) {
    queryMeta = {
      raw_query: entry.payload.raw_query as string | undefined,
      is_fulltext: entry.payload.is_fulltext as boolean | string | undefined,
      search_trace_id:
        entry.search_trace_id ||
        (entry.payload.search_trace_id as string | undefined),
    };
  }

  let errorCode: string | undefined;
  let errorBody: string | undefined;
  if (entry.status === 'error') {
    errorCode = 'ws_error';
    try {
      // Redact BEFORE stringify — once serialized, the global redactDeep()
      // pass can no longer see the object keys to redact.
      errorBody = JSON.stringify(redactDeep(entry.payload ?? '')).slice(0, 500);
    } catch {
      /* ignore */
    }
  } else if (entry.status === 'timeout') {
    errorCode = 'ws_timeout';
  }

  // Parallel to REST's `isDebugWorthy`: only record WS calls that matter
  // for debugging. Routine fast polls (pending-doc counts etc.) are dropped.
  const isWsDebugWorthy =
    entry.status !== 'ok' || entry.duration_ms >= SLOW_CALL_THRESHOLD_MS;
  if (!isWsDebugWorthy) return;

  apiCallBuffer.push({
    timestamp: new Date().toISOString(),
    method: 'WS',
    url,
    status: entry.status === 'ok' ? 200 : entry.status === 'timeout' ? 504 : 0,
    duration_ms: entry.duration_ms,
    request_headers: {},
    request_size_bytes: entry.request_size_bytes ?? 0,
    response_size_bytes: entry.response_size_bytes ?? 0,
    type,
    error_code: errorCode,
    error_body: errorBody,
    support_trace_id: entry.support_trace_id || entry.search_trace_id,
    search_trace_id: entry.search_trace_id,
    transport: 'websocket',
    query_meta: queryMeta,
    client_timing: entry.client_timing,
  });
}

