// --- API call classifier ---

/**
 * Classify an Axios URL into a coarse "type" so the Performance Report can group
 * slow calls by area (e.g. "dashboard is slow" vs "auth is slow"). Purely derived
 * at log time; services don't know they're being observed.
 */
export function classifyApiCall(url: string, _method: string): string {
  const path = extractPath(url).toLowerCase();

  if (path.includes('/document/dashboards')) return 'dashboard.documents';
  if (path.startsWith('/auth/')) {
    const segment = path.split('/')[2] ?? '';
    return segment ? `auth.${segment}` : 'auth.other';
  }
  if (/^\/document\/[a-z0-9-]+$/.test(path)) return 'document.detail';
  if (path.startsWith('/document/')) return 'document.other';

  return 'other';
}

function extractPath(url: string): string {
  try {
    if (url.startsWith('http')) return new URL(url).pathname;
  } catch {
    /* fall through */
  }
  const q = url.indexOf('?');
  return q >= 0 ? url.slice(0, q) : url;
}

// --- Collectors ---

function collectEnvironment(): Record<string, unknown> {
  const ua = navigator.userAgent;
  return {
    app_version: process.env.APP_VERSION || 'unknown',
    stage: process.env.APP_VUE_STAGE || 'unknown',
    branch: process.env.APP_VUE_BRANCH || '',
    browser: parseBrowser(ua),
    os: parseOS(ua),
    screen: `${screen.width}x${screen.height}`,
    viewport: `${window.innerWidth}x${window.innerHeight}`,
    locale: navigator.language,
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    user_agent: ua,
  };
}

function parseBrowser(ua: string): string {
  if (ua.includes('Chrome') && !ua.includes('Edg')) {
    const match = ua.match(/Chrome\/([\d.]+)/);
    return match ? `Chrome ${match[1]}` : 'Chrome';
  }
  if (ua.includes('Edg')) {
    const match = ua.match(/Edg\/([\d.]+)/);
    return match ? `Edge ${match[1]}` : 'Edge';
  }
  if (ua.includes('Firefox')) {
    const match = ua.match(/Firefox\/([\d.]+)/);
    return match ? `Firefox ${match[1]}` : 'Firefox';
  }
  if (ua.includes('Safari') && !ua.includes('Chrome')) {
    const match = ua.match(/Version\/([\d.]+)/);
    return match ? `Safari ${match[1]}` : 'Safari';
  }
  return 'Unknown';
}

function parseOS(ua: string): string {
  if (ua.includes('Windows NT 10')) return 'Windows 10/11';
  if (ua.includes('Windows')) return 'Windows';
  if (ua.includes('Mac OS X')) {
    const match = ua.match(/Mac OS X ([\d_]+)/);
    return match ? `macOS ${match[1].replace(/_/g, '.')}` : 'macOS';
  }
  if (ua.includes('Linux')) return 'Linux';
  if (ua.includes('Android')) return 'Android';
  if (ua.includes('iOS')) return 'iOS';
  return 'Unknown';
}

async function collectUserContext(
  orgId: string,
): Promise<Record<string, unknown>> {
  let userId = '';
  let email = '';
  let role = '';
  let isAdmin = false;
  let orgName = '';
  let subOrgId = '';

  // Read user details via getUserDetailFromkey (handles Quasar __q_objt encoding)
  try {
    const {
      getUserDetailFromkey,
      isUserAdmin,
      isOrganisationAdmin,
      isSupplierAdmin,
      isManagementUser,
    } = await import('src/utils/UserDetails');
    userId = getUserDetailFromkey('id');
    email = getUserDetailFromkey('username');
    isAdmin = isUserAdmin();

    // Derive role from boolean flags (no 'role' field exists in the data model)
    if (isOrganisationAdmin()) role = 'org_admin';
    else if (isSupplierAdmin()) role = 'supplier_admin';
    else if (isManagementUser()) role = 'management';
    else if (isAdmin) role = 'admin';
    else role = 'user';
  } catch {
    /* not available */
  }

  // Read org name and sub_org from user store
  try {
    const { useUserStore } = await import('src/store/User/user_details.store');
    const userStore = useUserStore();
    orgName = userStore.main_orgainzation || '';
    subOrgId = userStore.sub_org_id || '';
  } catch {
    /* store not initialized */
  }

  return {
    user_id: userId,
    org_id: orgId,
    email,
    role,
    is_admin: isAdmin,
    org_name: orgName,
    sub_org_id: subOrgId,
    active_route: redactUrlSecrets(
      window.location.hash?.replace('#', '') || window.location.pathname,
    ),
    session_duration_s: Math.round(performance.now() / 1000),
    page_load_time: new Date(performance.timeOrigin).toISOString(),
  };
}

async function collectWebSocket(): Promise<Record<string, unknown>> {
  try {
    // Dynamic import to avoid circular dependency — the WebSocket store's
    // import chain pulls in modules that reference App before it's initialized
    const { useWebSocketStore } = await import('src/store/websocket.store');
    const store = useWebSocketStore();
    // When was the last reconnect? If recent (< 60 s ago), the next
    // dashboard call probably hit the REST fallback path —
    // a slow `/document/dashboards` entry in api_calls is likely
    // explained by this rather than backend latency. Surface the
    // window so the perf-report reader can correlate.
    const now = Date.now();
    const lastDisc =
      store.lastDisconnectedAt instanceof Date
        ? store.lastDisconnectedAt.getTime()
        : 0;
    const lastConn =
      store.lastConnectedAt instanceof Date
        ? store.lastConnectedAt.getTime()
        : 0;
    return {
      state: store.connectionState || 'UNKNOWN',
      last_connected_at: store.lastConnectedAt?.toISOString() || null,
      last_disconnected_at: store.lastDisconnectedAt?.toISOString() || null,
      seconds_since_last_disconnect: lastDisc
        ? Math.round((now - lastDisc) / 1000)
        : null,
      seconds_since_last_connect: lastConn
        ? Math.round((now - lastConn) / 1000)
        : null,
      // True iff the WS was unstable in the last 60 s — a likely cause
      // of REST-fallback round-trips visible in api_calls below.
      recently_unstable: lastDisc > 0 && now - lastDisc < 60_000,
      total_reconnects: store.totalReconnects || 0,
      last_error: store.lastError ?? null,
      offline_queue_size: store.offlineMessageQueue?.length ?? 0,
      // WS connection URLs commonly carry an auth token as a query param
      // (browser WebSocket can't set headers) — redact before it leaves.
      url: redactUrlSecrets(store.socket?.url || ''),
      pending_request_timings: Array.from(
        store.wsClientTimings?.entries?.() ?? [],
      ).map(([requestId, timing]: any) => ({
        request_id: requestId,
        message_type: timing.message_type,
        support_trace_id: timing.support_trace_id,
        search_trace_id: timing.search_trace_id,
        raw_query: timing.raw_query,
        is_fulltext: timing.is_fulltext,
        sent_at: timing.sent_at,
        age_ms: Math.round(performance.now() - timing.sent_perf_ms),
        connect_wait_ms: timing.connect_wait_ms,
        request_size_bytes: timing.request_size_bytes,
      })),
    };
  } catch {
    return { state: 'UNAVAILABLE', error: 'Could not read WebSocket store' };
  }
}

function collectErrors(): ErrorEntry[] {
  return errorBuffer.toArray();
}

function collectPerformance(): Record<string, unknown> {
  const result: Record<string, unknown> = {
    lcp_ms: null,
    fcp_ms: null,
    cls: null,
    inp_ms: null,
    ttfb_ms: null,
    memory_mb: null,
    dom_nodes: document.getElementsByTagName('*').length,
    long_tasks_count: 0,
  };

  try {
    const paintEntries = performance.getEntriesByType('paint');
    for (const entry of paintEntries) {
      if (entry.name === 'first-contentful-paint') {
        result.fcp_ms = Math.round(entry.startTime);
      }
    }
    const navEntries = performance.getEntriesByType(
      'navigation',
    ) as PerformanceNavigationTiming[];
    if (navEntries.length > 0) {
      result.ttfb_ms = Math.round(
        navEntries[0].responseStart - navEntries[0].requestStart,
      );
    }
  } catch {
    /* performance API may not be fully available */
  }

  try {
    const mem = (performance as any).memory;
    if (mem) {
      result.memory_mb = Math.round(mem.usedJSHeapSize / (1024 * 1024));
    }
  } catch {
    /* not available */
  }

  return result;
}

function collectNetwork(): Record<string, unknown> {
  const conn = (navigator as any).connection;
  return {
    online: navigator.onLine,
    effective_type: conn?.effectiveType || null,
    downlink_mbps: conn?.downlink || null,
    rtt_ms: conn?.rtt || null,
  };
}

function collectStorage(): Record<string, unknown> {
  let localSize = 0;
  let sessionSize = 0;

  try {
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key) localSize += (localStorage.getItem(key) || '').length * 2;
    }
  } catch {
    /* localStorage not available */
  }

  try {
    for (let i = 0; i < sessionStorage.length; i++) {
      const key = sessionStorage.key(i);
      if (key) sessionSize += (sessionStorage.getItem(key) || '').length * 2;
    }
  } catch {
    /* sessionStorage not available */
  }

  return {
    localStorage_keys: localStorage.length,
    localStorage_size_kb: Math.round(localSize / 1024),
    sessionStorage_keys: sessionStorage.length,
    sessionStorage_size_kb: Math.round(sessionSize / 1024),
  };
}

export async function collectFeatureFlags(
  orgId: string,
): Promise<Record<string, unknown>> {
  try {
    const docnetSub =
      localStorage.getItem('docNetSubscription') ||
      localStorage.getItem('docnet_subscription');

    const subscriptions = new Set<string>();
    const modules = new Set<string>();

    const addSubscription = (name: unknown): void => {
      if (typeof name !== 'string') return;
      const normalized = name.trim().toLowerCase();
      if (normalized) subscriptions.add(normalized);
    };
    const addModule = (key: unknown): void => {
      if (typeof key !== 'string') return;
      const trimmed = key.trim();
      if (trimmed) modules.add(trimmed);
    };

    // Read from subscription store (authoritative, already fetched at login)
    try {
      const { useSubscriptionStore } =
        await import('src/store/User/subscription.store');
      const subStore = useSubscriptionStore();
      const subs = subStore.subscriptions;
      if (subs && typeof subs === 'object') {
        for (const sub of Object.values(subs)) {
          const name = (sub as any)?.name;
          addSubscription(name);
        }
      }
      // get_subscribed_apps returns active app_key list (e.g. FELLOW_DOC2, DOC_NET)
      const apps = subStore.get_subscribed_apps;
      if (Array.isArray(apps) && apps.length > 0) {
        apps.forEach(addModule);
      }
    } catch {
      /* store not initialized yet */
    }

    // Fall back to session cache for subscriptions if store wasn't ready
    if (subscriptions.size === 0) {
      try {
        const subRaw = sessionStorage.getItem('sub_app');
        if (subRaw) {
          const subCache = JSON.parse(subRaw);
          const cached = subCache?.value;
          if (Array.isArray(cached)) {
            for (const sub of cached) {
              addSubscription(sub?.name);
              // Also extract modules from cached subscription apps
              if (Array.isArray(sub?.apps)) {
                for (const app of sub.apps) {
                  addModule(app?.app_key);
                }
              }
            }
          } else if (cached && typeof cached === 'object') {
            addSubscription(cached.name);
            if (Array.isArray(cached.apps)) {
              for (const app of cached.apps) {
                addModule(app?.app_key);
              }
            }
          }
        }
      } catch {
        /* ignore parse errors */
      }
    }

    return {
      subscriptions:
        subscriptions.size > 0 ? Array.from(subscriptions) : ['unknown'],
      docnet_enabled: !!docnetSub,
      modules: Array.from(modules),
      org_settings_hash: orgId ? simpleHash(orgId) : '',
    };
  } catch {
    return {
      subscriptions: ['unknown'],
      docnet_enabled: false,
      modules: [],
      org_settings_hash: '',
    };
  }
}

function simpleHash(str: string): string {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash |= 0;
  }
  return Math.abs(hash).toString(16);
}

function collectTraceSummary(
  apiCalls: ApiCallEntry[],
  websocket: Record<string, unknown>,
): DebugSnapshot['trace_summary'] {
  const latestSupport = [...apiCalls]
    .reverse()
    .find((entry) => entry.support_trace_id);
  const latestApiSearch = [...apiCalls]
    .reverse()
    .find(
      (entry) => entry.search_trace_id || entry.query_meta?.search_trace_id,
    );
  const latestTempo = [...apiCalls]
    .reverse()
    .find((entry) => entry.tempo_trace_id || entry.trace_id);
  const pendingWs = Array.isArray(websocket.pending_request_timings)
    ? (websocket.pending_request_timings as Array<Record<string, unknown>>)
    : [];
  const latestWsSearch = [...pendingWs]
    .reverse()
    .find(
      (entry) =>
        typeof entry.search_trace_id === 'string' && entry.search_trace_id,
    );
  const latestWsSupport = [...pendingWs]
    .reverse()
    .find(
      (entry) =>
        typeof entry.support_trace_id === 'string' && entry.support_trace_id,
    );

  const latestSupportTraceId =
    latestSupport?.support_trace_id ||
    (latestWsSupport?.support_trace_id as string | undefined) ||
    getLastDocbitsTraceId() ||
    undefined;
  const latestSearchTraceId =
    latestApiSearch?.search_trace_id ||
    latestApiSearch?.query_meta?.search_trace_id ||
    (latestWsSearch?.search_trace_id as string | undefined);
  const latestTempoTraceId =
    latestTempo?.tempo_trace_id || latestTempo?.trace_id;
  const primaryTraceId =
    latestSupportTraceId || latestSearchTraceId || latestTempoTraceId;

  return {
    primary_trace_id: primaryTraceId,
    latest_support_trace_id: latestSupportTraceId,
    latest_search_trace_id: latestSearchTraceId,
    latest_tempo_trace_id: latestTempoTraceId,
    source: latestSupportTraceId
      ? 'docbits_trace_id'
      : latestSearchTraceId
        ? 'search_trace_id'
        : latestTempoTraceId
          ? 'tempo_trace_id'
          : undefined,
  };
}

// --- Snapshot Builder ---

export async function collectSnapshot(): Promise<DebugSnapshot> {
  let orgId = '';
  try {
    orgId = getOrgId() || '';
  } catch {}

  // Fetch service versions (non-blocking — if API is down, returns empty)
  let serviceVersions: DebugSnapshot['service_versions'] = [];
  try {
    const { default: AppsApiService } =
      await import('src/services/user/appsApiService');
    const svc = new AppsApiService();
    const versions = await Promise.race([
      svc.getAllVersions(),
      new Promise((_, reject) => setTimeout(() => reject('timeout'), 5000)),
    ]);
    if (Array.isArray(versions)) {
      serviceVersions = versions.map((v: any) => ({
        app: v.app || v.name || '',
        version: v.version || '',
        status: v.status || '',
        deployment_date: v.deployment_date || v.deployed_at || '',
      }));
    }
  } catch {
    /* API unavailable or timeout — skip */
  }

  // Headers are already redacted at capture time in recordAxiosResponse; this
  // re-redaction also covers entries pushed directly into the buffer. The
  // global redactDeep() pass below is the defense-in-depth net for every other
  // field (error bodies, console args, websocket payloads, …).
  const apiCalls = apiCallBuffer.toArray().map((entry) => ({
    ...entry,
    request_headers: redactHeaders(entry.request_headers),
    // Redact secret query params (?token=, ?code=, …) from the stored URL —
    // single chokepoint covering REST, WS, and directly-pushed entries.
    url: redactUrlSecrets(entry.url),
  }));
  const websocket = await collectWebSocket();

  const rawSnapshot: DebugSnapshot = {
    version: '1.0',
    generated_at: new Date().toISOString(),
    trace_summary: collectTraceSummary(apiCalls, websocket),
    environment: collectEnvironment(),
    user_context: await collectUserContext(orgId),
    api_calls: apiCalls,
    websocket,
    errors: collectErrors(),
    console_log: consoleBuffer.toArray(),
    performance: collectPerformance(),
    network: collectNetwork(),
    storage: collectStorage(),
    feature_flags: await collectFeatureFlags(orgId),
    service_versions: serviceVersions,
  };

  const snapshot = stripBannedTerms(redactDeep(rawSnapshot)) as DebugSnapshot;
  lastSnapshotRef.value = snapshot;
  return snapshot;
}

// --- Export Functions ---

export function downloadAsJson(snapshot: DebugSnapshot): void {
  const timestamp = snapshot.generated_at.replace(/[:.]/g, '-').slice(0, 19);
  const filename = `docbits-debug-${timestamp}.json`;
  const blob = new Blob([JSON.stringify(snapshot, null, 2)], {
    type: 'application/json',
  });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// --- Keyboard Shortcut Handler ---

export async function handleDebugShortcut(): Promise<void> {
  const snapshot = await collectSnapshot();
  const json = JSON.stringify(snapshot, null, 2);

  try {
    await navigator.clipboard.writeText(json);
  } catch {
    /* Clipboard may fail */
  }

  const apiCount = snapshot.api_calls.length;
  const errorCount = snapshot.errors.length;
  const lcpVal = snapshot.performance.lcp_ms;
  const lcp =
    lcpVal != null ? `${((lcpVal as number) / 1000).toFixed(1)}s` : 'N/A';

  notify.success('Debug data copied to clipboard', {
    description: `Trace ${snapshot.trace_summary.primary_trace_id || 'N/A'} · ${apiCount} API calls · ${errorCount} errors · LCP ${lcp}`,
    duration: 8000,
    action: {
      label: 'Show Details',
      onClick: () => {
        debugModalOpen.value = true;
      },
    },
  });
}

// --- Axios Interceptor Hook ---

// Convert AxiosHeaders (class instance) to a plain Record for redactHeaders
function toPlainHeaders(headers: unknown): Record<string, string> {
  if (!headers) return {};
  // AxiosHeaders has a toJSON() method that returns a plain object
  if (typeof (headers as any).toJSON === 'function') {
    return (headers as any).toJSON(true) as Record<string, string>;
  }
  // Already a plain object
  if (typeof headers === 'object') {
    const result: Record<string, string> = {};
    for (const [k, v] of Object.entries(headers as Record<string, unknown>)) {
      result[k] = String(v ?? '');
    }
    return result;
  }
  return {};
}

function headerValue(
  headers: Record<string, string>,
  name: string,
): string | undefined {
  const wanted = name.toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() === wanted && value) return value;
  }
  return undefined;
}

function traceIdFromTraceparent(traceparent?: string): string | undefined {
  if (!traceparent) return undefined;
  const parts = traceparent.trim().split('-');
  const traceId = parts[1];
  if (parts.length >= 4 && /^[0-9a-f]{32}$/i.test(traceId)) return traceId;
  return undefined;
}

/**
 * Register debug interceptors on any Axios instance.
 * Call this on each instance that handles API traffic.
 * The interceptor is transparent — it records the call and passes through.
 */
interface DebugInterceptorOptions {
  recordPerformanceStore?: boolean;
}

export function registerDebugInterceptor(
  instance: import('axios').AxiosInstance,
  options: DebugInterceptorOptions = {},
): void {
  const recordPerformanceStore = options.recordPerformanceStore ?? true;
  instance.interceptors.response.use(
    (response) => {
      recordAxiosResponse(
        response.config,
        response.status,
        response.data,
        response.headers,
        { recordPerformanceStore },
      );
      return response;
    },
    (error) => {
      recordAxiosResponse(
        error?.config,
        error?.response?.status || 0,
        error?.response?.data,
        error?.response?.headers,
        { recordPerformanceStore },
      );
      return Promise.reject(error);
    },
  );
}

// If `data` is a string that holds a serialized JSON object/array, parse it so
// key-based redaction can run on the structure; otherwise return it unchanged.
function parseMaybeJson(data: unknown): unknown {
  if (typeof data !== 'string') return data ?? '';
  const trimmed = data.trim();
  if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
    try {
      return JSON.parse(trimmed);
    } catch {
      /* not JSON — fall through */
    }
  }
  return data;
}

// Only record calls that are useful for debugging:
// - Slow calls (≥ threshold from performanceStore — single source of truth)
// - Error status codes (4xx, 5xx, or 0 for network failures)
// - Responses with success: false
function isDebugWorthy(
  status: number,
  duration: number,
  data: unknown,
): boolean {
  if (status === 0 || status >= 400) return true;
  if (duration >= SLOW_CALL_THRESHOLD_MS) return true;
  if (data && typeof data === 'object' && (data as any).success === false)
    return true;
  return false;
}

function failureMessageFromData(data: unknown, fallback = ''): string {
  if (!data || typeof data !== 'object') return fallback;
  const candidate = (data as any).message ?? (data as any).detail;
  if (candidate === undefined || candidate === null) return fallback;
  if (typeof candidate === 'string') return candidate;
  try {
    return JSON.stringify(redactDeep(candidate)).slice(0, 500);
  } catch {
    return String(candidate);
  }
}

function recordAxiosResponse(
  config: any,
  status: number,
  data: unknown,
  responseHeaders?: unknown,
  options: DebugInterceptorOptions = {},
): void {
  const recordPerformanceStore = options.recordPerformanceStore ?? true;
  // Support both __requestStartTime (AXIOS_INSTANCE) and metadata.startTime (ApiClient)
  const startTime = config?.__requestStartTime || config?.metadata?.startTime;
  let duration = 0;
  if (typeof startTime === 'number') {
    duration = Date.now() - startTime;
  } else if (startTime instanceof Date) {
    duration = Date.now() - startTime.getTime();
  }

  const url = String(config?.url ?? 'unknown');
  const method = String(config?.method ?? 'UNKNOWN').toUpperCase();
  const type = classifyApiCall(url, method);
  const requestHeaders = toPlainHeaders(config?.headers);
  const responseHeaderMap = toPlainHeaders(responseHeaders);
  const serverTiming = parseServerTiming(
    headerValue(responseHeaderMap, 'server-timing'),
  );
  const supportTraceId =
    headerValue(responseHeaderMap, 'x-docbits-trace-id') ||
    headerValue(requestHeaders, 'x-docbits-trace-id') ||
    config?.__docbitsTraceId ||
    traceIdFromTraceparent(headerValue(requestHeaders, 'traceparent'));
  const searchTraceId =
    headerValue(responseHeaderMap, 'x-search-trace-id') ||
    headerValue(requestHeaders, 'x-search-trace-id') ||
    config?.__searchTraceId;
  const tempoTraceId =
    headerValue(responseHeaderMap, 'x-trace-id') ||
    traceIdFromTraceparent(headerValue(requestHeaders, 'traceparent'));

  // Feed slow calls into performanceStore so the "Slow API Calls" section
  // in PerformanceAnalysisDialog works for ALL axios instances, not just the default
  const isFaro = url.includes('.faro.docbits.com');
  const isHealth =
    url.includes('/health') || url.includes('/ping') || url.includes('/status');
  if (
    recordPerformanceStore &&
    duration >= SLOW_CALL_THRESHOLD_MS &&
    !isFaro &&
    !isHealth
  ) {
    recordSlowCall({
      url,
      method,
      duration,
      status,
      type,
      timestamp: new Date().toISOString(),
      serverTiming,
      traceId: tempoTraceId,
      supportTraceId,
      searchTraceId,
    });
  }

  const isSoftFailure =
    status >= 200 &&
    status < 300 &&
    !!data &&
    typeof data === 'object' &&
    (data as any).success === false;
  if (
    recordPerformanceStore &&
    (status >= 400 || status === 0 || isSoftFailure) &&
    !isFaro &&
    !isHealth
  ) {
    const fallback = isSoftFailure ? 'success=false' : '';
    const message = failureMessageFromData(data, fallback);
    recordFailedCall({
      url,
      method,
      duration,
      status,
      type,
      statusText: message,
      timestamp: new Date().toISOString(),
      serverTiming,
      traceId: tempoTraceId,
      supportTraceId,
      searchTraceId,
      softFailure: isSoftFailure,
      message,
    });
  }

  if (!isDebugWorthy(status, duration, data)) return;

  // Use the RESPONSE Content-Length header if available, otherwise estimate
  // from data. (Reading config.headers here would record the request size.)
  let responseSize = 0;
  const contentLength = headerValue(responseHeaderMap, 'content-length');
  if (contentLength) {
    responseSize = parseInt(contentLength, 10) || 0;
  } else if (data) {
    try {
      responseSize = JSON.stringify(data).length;
    } catch {
      /* ignore */
    }
  }

  let requestSize = 0;
  if (config?.data !== undefined && config?.data !== null) {
    try {
      requestSize =
        typeof config.data === 'string'
          ? config.data.length
          : JSON.stringify(config.data).length;
    } catch {
      /* ignore */
    }
  }

  let errorCode: string | undefined;
  let errorBody: string | undefined;
  if (status >= 400 || status === 0) {
    errorCode = String(status);
    try {
      // Redact secrets BEFORE storing: error payloads from auth endpoints can
      // echo tokens/credentials. JSON strings are parsed so key-based redaction
      // applies (e.g. a serialized {"Authorization":"Bearer …"} body); objects
      // are redacted field-by-field; other strings by pattern.
      const redacted = redactDeep(parseMaybeJson(data));
      errorBody = (
        typeof redacted === 'string' ? redacted : JSON.stringify(redacted)
      ).slice(0, 500);
    } catch {
      /* ignore */
    }
  }

  // For dashboard requests, parse out raw_query + is_fulltext from the
  // URL so the perf report shows them inline (otherwise the reader has
  // to URL-decode the long query-string by hand).
  let queryMeta: ApiCallEntry['query_meta'];
  if (url.includes('/document/dashboards')) {
    try {
      const qIdx = url.indexOf('?');
      if (qIdx >= 0) {
        const params = new URLSearchParams(url.slice(qIdx + 1));
        const raw = params.get('raw_query');
        const isFt = params.get('is_fulltext');
        if (raw != null || isFt != null) {
          queryMeta = {
            raw_query: raw ?? undefined,
            is_fulltext: isFt ?? undefined,
            search_trace_id: searchTraceId,
          };
        }
      }
    } catch {
      /* ignore */
    }
  }

  apiCallBuffer.push({
    timestamp: new Date().toISOString(),
    method,
    url,
    status,
    duration_ms: duration,
    // Redact at capture time so secrets never sit raw in the buffer
    // (which is also reachable via the exported getApiCallBuffer()).
    request_headers: redactHeaders(requestHeaders),
    request_size_bytes: requestSize,
    response_size_bytes: responseSize,
    type,
    error_code: errorCode,
    error_body: errorBody,
    trace_id: tempoTraceId,
    tempo_trace_id: tempoTraceId,
    support_trace_id: supportTraceId,
    search_trace_id: searchTraceId,
    transport: 'rest',
    query_meta: queryMeta,
  });
}

function setupAxiosInterceptor(): void {
  // Register on the default axios instance (catches any direct axios.get/post calls)
  // axiosInterceptor.js already feeds default axios slow/failed calls into
  // performanceStore; keep this interceptor focused on the debug snapshot.
  registerDebugInterceptor(axios, { recordPerformanceStore: false });
}

// --- Console Wrapper ---

let consoleWrapped = false;
let insideWrapper = false;

function safeStringify(a: unknown): string {
  if (typeof a === 'string') return a;
  try {
    return JSON.stringify(a);
  } catch {
    return String(a);
  }
}

function setupConsoleWrapper(): void {
  if (consoleWrapped) return;
  consoleWrapped = true;

  const levels = ['log', 'info', 'warn', 'error'] as const;
  for (const level of levels) {
    const original = console[level];
    console[level] = (...args: unknown[]) => {
      // Re-entrancy guard: if our wrapper triggers a console call (e.g. via
      // JSON.stringify getter), pass through to the original without recording
      if (insideWrapper) {
        original.apply(console, args);
        return;
      }
      insideWrapper = true;
      try {
        // Redact args FIRST, then derive the message string from the redacted
        // args — otherwise a logged object like { Authorization: 'Bearer …' }
        // would leak in `message` even though `args` are redacted.
        const redactedArgs = redactConsoleArgs(
          args.map((a) => {
            try {
              return typeof a === 'object' ? JSON.parse(JSON.stringify(a)) : a;
            } catch {
              return String(a);
            }
          }),
        );
        consoleBuffer.push({
          timestamp: new Date().toISOString(),
          level,
          message: redactedArgs.map(safeStringify).join(' '),
          args: redactedArgs,
        });
      } catch {
        /* never break console calls */
      }
      insideWrapper = false;
      original.apply(console, args);
    };
  }
}

// --- Keyboard Listener ---

// --- Boot Export ---

export default safeBoot('debugCollector', () => {
  setupAxiosInterceptor();
  setupConsoleWrapper();
});
