/**
 * In-memory store for slow and failed API calls.
 * Populated by the axios interceptor, read by PerformanceAnalysisDialog.
 */

export interface ServerTiming {
  total?: number; // ms — total server processing time
  db?: number; // ms — database query time
  cache?: number; // ms — Redis cache time
}

export interface SlowCall {
  url: string;
  method: string;
  duration: number; // ms
  status: number;
  timestamp: string; // ISO
  type: string; // classifier, e.g. "dashboard.documents"
  serverTiming?: ServerTiming;
  traceId?: string;
  supportTraceId?: string;
  searchTraceId?: string;
}

export interface FailedCall {
  url: string;
  method: string;
  duration: number; // ms
  status: number;
  statusText: string;
  timestamp: string; // ISO
  type: string; // classifier, e.g. "dashboard.documents"
  serverTiming?: ServerTiming;
  traceId?: string;
  supportTraceId?: string;
  searchTraceId?: string;
  softFailure?: boolean; // HTTP 200 but success=false in response body
  message?: string; // Error message from response body
}

/** Calls slower than this (ms) are tracked in the store for the dialog. */
export const SLOW_CALL_THRESHOLD_MS = 2000;

const MAX_ENTRIES = 50;
const _calls: SlowCall[] = [];
const _failedCalls: FailedCall[] = [];

export function recordSlowCall(call: SlowCall): void {
  _calls.push(call);
  if (_calls.length > MAX_ENTRIES) {
    _calls.shift();
  }
}

export function recordFailedCall(call: FailedCall): void {
  _failedCalls.push(call);
  if (_failedCalls.length > MAX_ENTRIES) {
    _failedCalls.shift();
  }
}

export function getSlowCalls(): SlowCall[] {
  return [..._calls];
}

export function getFailedCalls(): FailedCall[] {
  return [..._failedCalls];
}

export function clearSlowCalls(): void {
  _calls.length = 0;
}

export function clearFailedCalls(): void {
  _failedCalls.length = 0;
}

/**
 * Parse the W3C Server-Timing header into a structured object.
 *
 * Example input: 'total;dur=142.5;desc="Total", db;dur=85.2;desc="Database", cache;dur=10.1'
 * Output: { total: 142.5, db: 85.2, cache: 10.1 }
 */
export function parseServerTiming(header: string | null | undefined): ServerTiming | undefined {
  if (!header) return undefined;

  const timing: ServerTiming = {};
  const entries = header.split(',');

  for (const entry of entries) {
    const parts = entry.trim().split(';');
    const name = parts[0]?.trim();
    const durPart = parts.find((p) => p.trim().startsWith('dur='));
    if (!name || !durPart) continue;

    const dur = parseFloat(durPart.trim().replace('dur=', ''));
    if (isNaN(dur)) continue;

    if (name === 'total') timing.total = dur;
    else if (name === 'db') timing.db = dur;
    else if (name === 'cache') timing.cache = dur;
  }

  return Object.keys(timing).length > 0 ? timing : undefined;
}
