export const REDACTED = '[REDACTED]';

const MAX_BODY_SIZE = 10 * 1024; // 10KB

const SENSITIVE_HEADER_NAMES = /^(authorization|cookie|set-cookie)$/i;
const SENSITIVE_HEADER_KEYWORDS = /token|secret|password|key/i;
const SENSITIVE_VALUE_PATTERNS = /(^|\s)bearer\s+\S/i;
const SENSITIVE_VALUE_KEYWORDS = /api[_-]?token|api[_-]?key|password|secret/i;
// A JWT (header.payload.signature, base64url) — distinctive `eyJ` prefix means
// negligible false positives. Catches opaque tokens logged as bare strings.
const JWT_PATTERN = /eyJ[A-Za-z0-9_-]{4,}\.[A-Za-z0-9_-]{4,}\.[A-Za-z0-9_-]{4,}/;
// Object KEYS whose value must always be redacted, regardless of where the
// object is nested (e.g. `{ Authorization: 'Bearer …' }` inside a console arg).
// Note: bare "session" is intentionally excluded so legitimate fields like
// `session_duration_s` survive; session secrets are covered by `token` /
// `session_id` instead.
const SENSITIVE_KEY_NAMES = /authorization|cookie|passwd|password|secret|token|api[_-]?key|credential|session[_-]?id|jwt/i;

export function redactHeaders(headers: Record<string, string>): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [name, value] of Object.entries(headers)) {
    if (SENSITIVE_HEADER_NAMES.test(name) || SENSITIVE_HEADER_KEYWORDS.test(name)) {
      result[name] = REDACTED;
    } else {
      result[name] = value;
    }
  }
  return result;
}

// Redact secret-bearing query/fragment parameter VALUES in a URL, e.g.
// `?token=…`, `&code=…`, `#/reset?access_token=…`. Path-embedded secrets are
// not handled (ambiguous vs legitimate path IDs like /document/<uuid>).
const SENSITIVE_QUERY_PARAM =
  /([?&#][^=&#\s]*?(?:token|secret|password|passwd|pwd|api[_-]?key|apikey|credential|session|sid|jwt|signature|sig|code|auth)[^=&#\s]*=)([^&#\s]*)/gi;

export function redactUrlSecrets(url: string): string {
  if (typeof url !== 'string' || !url) return url;
  return url.replace(SENSITIVE_QUERY_PARAM, `$1${REDACTED}`);
}

export function redactValue(value: unknown): unknown {
  if (typeof value !== 'string') return value;
  if (
    SENSITIVE_VALUE_PATTERNS.test(value) ||
    SENSITIVE_VALUE_KEYWORDS.test(value) ||
    JWT_PATTERN.test(value)
  ) {
    return REDACTED;
  }
  return value;
}

export function truncateBody(body: unknown): unknown {
  if (body === null || body === undefined) return body;

  let serialized: string;
  try {
    serialized = typeof body === 'string' ? body : JSON.stringify(body);
  } catch {
    return '[Unserializable]';
  }

  if (serialized.length <= MAX_BODY_SIZE) {
    return body;
  }

  return serialized.slice(0, MAX_BODY_SIZE) + `\n[TRUNCATED — original ${serialized.length} bytes]`;
}

export const BANNED_TERMS: readonly string[] = [
  'ChatGPT',
  'OpenAI',
  'GPT-4',
  'GPT-3.5',
  'AWS',
  'Azure',
  'Google Cloud',
];

const REGEX_METACHARACTERS = /[.*+?^${}()|[\]\\]/g;

function escapeForRegex(term: string): string {
  return term.replace(REGEX_METACHARACTERS, '\\$&');
}

function buildBannedTermsPattern(): RegExp | null {
  if (BANNED_TERMS.length === 0) return null;
  const alternation = BANNED_TERMS.map(escapeForRegex).join('|');
  return new RegExp(alternation, 'gi');
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function stripWithPattern(value: unknown, pattern: RegExp): unknown {
  if (typeof value === 'string') return value.replace(pattern, '');
  if (Array.isArray(value)) return value.map((item) => stripWithPattern(item, pattern));
  if (isPlainObject(value)) {
    const result: Record<string, unknown> = {};
    for (const [key, val] of Object.entries(value)) {
      result[key] = stripWithPattern(val, pattern);
    }
    return result;
  }
  return value;
}

export function stripBannedTerms(value: unknown): unknown {
  const pattern = buildBannedTermsPattern();
  if (pattern === null) return value;
  return stripWithPattern(value, pattern);
}

/**
 * Recursively redact secrets from an arbitrary value (string, array, or plain
 * object). Strings matching sensitive patterns become `[REDACTED]`; object
 * values whose KEY name looks sensitive (Authorization, token, password, …) are
 * redacted wholesale. Non-plain objects (class instances, etc.) are returned
 * untouched to avoid traversing host objects.
 */
export function redactDeep(value: unknown, seen: WeakSet<object> = new WeakSet()): unknown {
  if (typeof value === 'string') return redactValue(value);
  // `seen` tracks only the CURRENT ancestor chain (entries are removed once a
  // subtree is fully processed), so genuine cycles become '[Circular]' while
  // shared/DAG references that aren't cyclic are still redacted normally.
  if (Array.isArray(value)) {
    if (seen.has(value)) return '[Circular]';
    seen.add(value);
    const result = value.map((item) => redactDeep(item, seen));
    seen.delete(value);
    return result;
  }
  if (isPlainObject(value)) {
    if (seen.has(value)) return '[Circular]';
    seen.add(value);
    const result: Record<string, unknown> = {};
    for (const [key, val] of Object.entries(value)) {
      result[key] = SENSITIVE_KEY_NAMES.test(key) ? REDACTED : redactDeep(val, seen);
    }
    seen.delete(value);
    return result;
  }
  return value;
}

export function redactConsoleArgs(args: unknown[]): unknown[] {
  return args.map((arg) => stripBannedTerms(redactDeep(arg)));
}
